import sys

def longestSubstring(N, S):
    def search(length):
        seen = set()
        for i in range(N - length + 1):
            substring = S[i:i+length]
            if substring in seen:
                return substring
            seen.add(substring)
        return None

    longest = -1
    for length in range(1, N // 2 + 1):
        result = search(length)
        if result:
            longest = result
    return longest if longest != -1 else -1

if __name__ == "__main__":
    input = sys.stdin.read().split()
    N = int(input[0])
    S = input[1]
    print(longestSubstring(N, S))
